LANGUAGE plpgsql
AS $$
DECLARE
    v_threshold integer := arg1;
    v_initial_threshold integer := arg1;
    v_status text := arg2;
    v_operation text := arg3;
    v_handled_count integer := 0;
    v_batch_size integer := 10;
    v_state text := 'INIT';
    v_high_priority_seen boolean := false;
    r_rest record;
    r_stu record;
    r_kind record;
BEGIN
    IF v_initial_threshold < 3 THEN
        v_state := 'MINIMAL_PROCESS';

        FOR r_rest IN
            SELECT ResID, ResName, Address
            FROM Restaurant
            WHERE ResID < arg1
              AND ResName LIKE arg2
        LOOP
            v_handled_count := v_handled_count + 1;

            IF r_rest.ResID > 25 THEN
                UPDATE Restaurant
                SET ResName = 'PROMOTED'
                WHERE ResID = r_rest.ResID;
            ELSIF r_rest.Address = v_operation THEN
                DELETE FROM Visits_Restaurant
                WHERE ResID = r_rest.ResID;

                DELETE FROM Type_Of_Restaurant
                WHERE ResID = r_rest.ResID;

                DELETE FROM Restaurant
                WHERE ResID = r_rest.ResID
                  AND ResName = r_rest.ResName;
            ELSE
                UPDATE Restaurant
                SET Address = 'PENDING'
                WHERE ResID = r_rest.ResID;
            END IF;

            IF v_handled_count >= v_batch_size THEN
                v_batch_size := v_batch_size + 5;
            END IF;
        END LOOP;

    ELSIF v_initial_threshold < 8 THEN
        v_state := 'STANDARD_PROCESS';

        FOR r_stu IN
            SELECT StuID, LName, city_code
            FROM Student
            WHERE StuID BETWEEN arg4 - 5 AND arg4 + 15
        LOOP
            v_handled_count := v_handled_count + 1;

            IF r_stu.city_code = arg3 THEN
                UPDATE Student
                SET Sex = 'U'
                WHERE StuID = r_stu.StuID;
            END IF;

            IF r_stu.LName = arg5 THEN
                UPDATE Student
                SET city_code = 'MATCHED'
                WHERE StuID = r_stu.StuID;
            END IF;

            IF r_stu.LName LIKE 'ACTIVE%' THEN
                UPDATE Student
                SET LName = 'PROCESSED'
                WHERE StuID = r_stu.StuID;
            ELSIF r_stu.StuID > arg4 + 5 THEN
                v_threshold := v_threshold + r_stu.StuID;
            ELSE
                DELETE FROM Student
                WHERE StuID = r_stu.StuID
                  AND LName = 'EXPIRED';
            END IF;

            IF v_handled_count >= v_batch_size THEN
                v_batch_size := v_batch_size + 5;
            END IF;
        END LOOP;

    ELSIF v_initial_threshold < 18 THEN
        v_state := 'ENHANCED_PROCESS';

        FOR r_kind IN
            SELECT ResTypeID
            FROM Type_Of_Restaurant
            WHERE ResTypeID > arg6 - 20
        LOOP
            v_handled_count := v_handled_count + 1;

            IF r_kind.ResTypeID < 50 THEN
                v_status := 'LOW_PRIORITY';
            ELSIF r_kind.ResTypeID < 150 THEN
                v_status := 'MEDIUM_PRIORITY';
            ELSE
                v_status := 'HIGH_PRIORITY';
                v_high_priority_seen := true;
            END IF;

            UPDATE Type_Of_Restaurant
            SET ResTypeID = ResTypeID + 10
            WHERE ResTypeID = r_kind.ResTypeID;

            IF v_handled_count >= v_batch_size THEN
                v_batch_size := v_batch_size + 5;
            END IF;
        END LOOP;

    ELSIF v_initial_threshold < 25 THEN
        v_state := 'ARCHIVE_MODE';

        UPDATE Restaurant
        SET Address = 'ARCHIVED'
        WHERE ResID < arg1
          AND ResName <> v_status;

    ELSIF v_initial_threshold < 40 THEN
        v_state := 'CLEANUP_MODE';

        DELETE FROM Student
        WHERE StuID < arg4
          AND LName = 'OBSOLETE';

    ELSE
        v_state := 'BOOST_MODE';

        UPDATE Type_Of_Restaurant
        SET ResTypeID = arg6 + 100
        WHERE ResTypeID > 200;
    END IF;

    IF v_status = 'HIGH_PRIORITY' OR v_high_priority_seen THEN
        UPDATE Type_Of_Restaurant
        SET ResTypeID = ResTypeID * 2
        WHERE ResTypeID > 100;
    ELSIF v_state = 'ARCHIVE_MODE' THEN
        DELETE FROM Restaurant
        WHERE Address = 'ARCHIVED'
          AND ResID < v_threshold - 10;
    ELSIF v_handled_count > 15 THEN
        UPDATE Student
        SET LName = 'BULK_PROCESSED'
        WHERE StuID BETWEEN arg4 AND arg4 + 50;
    ELSE
        UPDATE Restaurant
        SET ResName = v_operation
        WHERE ResID > v_threshold;
    END IF;
